export interface WasmSearchCallbacks {
  readonly nowMs: () => number;
  readonly pollStatus: (nodes: number, depth: number, score: number, bestCode: number, forceProgress: number) => number;
  readonly ttProbe: (
    keyLo: number, keyHi: number, b0: number, b1: number, b2: number,
    w0: number, w1: number, w2: number, activeClaims: number, rem: number, qleft: number, ttSafe: number,
    ioOut: Float64Array,
  ) => number;
  readonly ttStore: (
    keyLo: number, keyHi: number, b0: number, b1: number, b2: number,
    w0: number, w1: number, w2: number, activeClaims: number, rem: number, qleft: number, ttSafe: number,
    val: number, move: number, bnd: number,
  ) => void;
}

export interface WasmSearchResult {
  readonly bestCode: number;
  readonly score: number;
  readonly nodes: number;
  readonly completedDepth: number;
  readonly maxVisitedDepth: number;
  readonly cutoffs: number;
  readonly rootCandidates: number;
  readonly stopCode: number;
}

interface WasmMemory {
  readonly buffer: ArrayBuffer;
}

interface WasmNamespace {
  readonly Module: new (bytes: Uint8Array) => object;
  readonly Instance: new (mod: object, imports: Record<string, Record<string, unknown>>) => { readonly exports: unknown };
}

interface WasmExports {
  readonly memory: WasmMemory;
  readonly wasm_init: () => void;
  readonly wasm_model_buf_ptr: () => number;
  readonly wasm_moves_buf_ptr: () => number;
  readonly wasm_tt_io_ptr: () => number;
  readonly wasm_result_buf_ptr: () => number;
  readonly wasm_load_model: (byteLen: number, blendOv: number, claimOv: number, enableI16: number) => number;
  readonly wasm_search: (
    swap3: number, moveCount: number, nodeBudget: number, timeMs: number,
    maxDepth: number, seed: number, flags: number, threadId: number,
  ) => number;
}

let activeCallbacks: WasmSearchCallbacks | null = null;
let cachedExports: WasmExports | null = null;
let cachedTtIo: Float64Array | null = null;
let wasmInitFailed = false;

function ensureWasmKernel(): WasmExports | null {
  if (cachedExports) return cachedExports;
  if (wasmInitFailed) return null;
  try {
    const WA = (globalThis as unknown as { WebAssembly?: WasmNamespace }).WebAssembly;
    if (!WA || typeof WA.Module !== "function") {
      wasmInitFailed = true;
      return null;
    }
    const bytes = decodeBase64(WASM_SIMD_B64);
    const mod = new WA.Module(bytes);
    const inst = new WA.Instance(mod, {
      env: {
        now_ms: (): number => activeCallbacks ? activeCallbacks.nowMs() : 0,
        poll_status: (nodes: number, depth: number, score: number, bestCode: number, forceProgress: number): number =>
          activeCallbacks ? activeCallbacks.pollStatus(nodes, depth, score, bestCode, forceProgress) : 0,
        tt_probe: (
          kl: number, kh: number, b0: number, b1: number, b2: number,
          w0: number, w1: number, w2: number, ac: number, rem: number, ql: number, ts: number,
        ): number => (activeCallbacks && cachedTtIo)
          ? activeCallbacks.ttProbe(kl | 0, kh | 0, b0 | 0, b1 | 0, b2 | 0, w0 | 0, w1 | 0, w2 | 0, ac, rem, ql, ts, cachedTtIo)
          : 0,
        tt_store: (
          kl: number, kh: number, b0: number, b1: number, b2: number,
          w0: number, w1: number, w2: number, ac: number, rem: number, ql: number, ts: number,
          val: number, mv: number, bnd: number,
        ): void => {
          if (activeCallbacks) {
            activeCallbacks.ttStore(kl | 0, kh | 0, b0 | 0, b1 | 0, b2 | 0, w0 | 0, w1 | 0, w2 | 0, ac, rem, ql, ts, val, mv, bnd);
          }
        },
      },
    });
    const ex = inst.exports as unknown as WasmExports;
    ex.wasm_init();
    const modelBin = getNnueBinary();
    const mPtr = ex.wasm_model_buf_ptr();
    new Uint8Array(ex.memory.buffer, mPtr, modelBin.byteLength).set(modelBin);
    const ok = ex.wasm_load_model(modelBin.byteLength, NNUE_BLEND_ALPHA, NNUE_CLAIM_BLEND_ALPHA, 0);
    if (!ok) {
      wasmInitFailed = true;
      return null;
    }
    cachedTtIo = new Float64Array(ex.memory.buffer, ex.wasm_tt_io_ptr(), 4);
    cachedExports = ex;
    return ex;
  } catch {
    wasmInitFailed = true;
    return null;
  }
}

export function warmupV24WasmKernel(): boolean {
  return ensureWasmKernel() !== null;
}

export function runV24WasmSearch(
  swap3: boolean,
  moveCodes: readonly number[],
  nodeBudget: number,
  timeMs: number,
  maxDepth: number,
  seed: number,
  flags: number,
  threadId: number,
  callbacks: WasmSearchCallbacks,
): WasmSearchResult | null {
  if (moveCodes.length > 512) return null;
  const ex = ensureWasmKernel();
  if (!ex) return null;
  const mvPtr = ex.wasm_moves_buf_ptr();
  const mvView = new Int32Array(ex.memory.buffer, mvPtr, moveCodes.length);
  for (let i = 0; i < moveCodes.length; i++) mvView[i] = moveCodes[i]!;
  const prevCb = activeCallbacks;
  activeCallbacks = callbacks;
  try {
    const best = ex.wasm_search(
      swap3 ? 1 : 0,
      moveCodes.length,
      nodeBudget | 0,
      timeMs,
      maxDepth | 0,
      seed >>> 0,
      flags | 0,
      threadId | 0,
    );
    if (best < 0) return null;
    const r = new Float64Array(ex.memory.buffer, ex.wasm_result_buf_ptr(), 8);
    return {
      bestCode: r[0]! | 0,
      score: r[1]!,
      nodes: r[2]! | 0,
      completedDepth: r[3]! | 0,
      maxVisitedDepth: r[4]! | 0,
      cutoffs: r[5]! | 0,
      rootCandidates: r[6]! | 0,
      stopCode: r[7]! | 0,
    };
  } finally {
    activeCallbacks = prevCb;
  }
}
